// The paws and item follow the same path, so the cashier actually holds the shopping.
window.CashierMotion=class {
 constructor(scene){this.scene=scene;this.arms=document.createElementNS('http://www.w3.org/2000/svg','svg');this.arms.classList.add('cashier-arms');this.arms.setAttribute('aria-hidden','true');this.held=document.createElement('div');this.held.className='held-shopping';this.held.setAttribute('aria-hidden','true');scene.append(this.held,this.arms);this.reset();}
 measure(){const origin=this.scene.getBoundingClientRect(),helper=document.getElementById('helper').getBoundingClientRect(),item=this.source.getBoundingClientRect(),scanner=document.getElementById('scanner').getBoundingClientRect(),bag=document.getElementById('shopping-bag').getBoundingClientRect();const point=(x,y)=>({x:x-origin.x,y:y-origin.y});this.geometry={width:origin.width,height:origin.height,itemWidth:item.width,itemHeight:item.height,source:point(item.x+item.width/2,item.y+item.height/2),scan:point(scanner.x+scanner.width/2,scanner.y-item.height*.30),aboveBag:point(bag.x+bag.width/2,bag.y-item.height*.48-24),insideBag:point(bag.x+bag.width/2,bag.y+28),leftShoulder:point(helper.x+helper.width*.31,helper.y+helper.height*.76),rightShoulder:point(helper.x+helper.width*.72,helper.y+helper.height*.76)};this.arms.setAttribute('viewBox',`0 0 ${origin.width} ${origin.height}`);this.held.style.width=item.width+'px';this.held.style.height=item.height+'px';}
 start(source){this.reset();this.source=source;this.scene.classList.add('cashier-handling');this.measure();this.held.innerHTML=source.innerHTML;this.arms.style.display='block';this.step(0);}
 reset(){if(this.source)this.source.style.visibility='';this.source=null;this.stage='rest';this.scene.classList.remove('cashier-handling');document.getElementById('helper').style.transform='';this.arms.style.display='none';this.held.style.display='none';this.arms.replaceChildren();}
 mix(a,b,t){const s=t*t*(3-2*t);return {x:a.x+(b.x-a.x)*s,y:a.y+(b.y-a.y)*s};}
 step(t,gentle=false){if(!this.source)return;const g=this.geometry;if(gentle){this.stage='bag';this.source.style.visibility='hidden';this.arms.style.display='none';this.held.style.display='none';return;}
 let item=g.source,left,right,angle=0,scale=1;const maxLean=Math.min(g.itemWidth*.95,Math.max(0,g.leftShoulder.x-g.source.x-g.itemWidth)),lean=t<.18?maxLean*this.mix({x:0,y:0},{x:1,y:0},t/.18).x:t<.58?maxLean:t<.85?maxLean*(1-this.mix({x:0,y:0},{x:1,y:0},(t-.58)/.27).x):0,leftShoulder={x:g.leftShoulder.x-lean,y:g.leftShoulder.y},rightShoulder={x:g.rightShoulder.x-lean,y:g.rightShoulder.y};document.getElementById('helper').style.transform=`translateX(${-lean}px)`;const grip=p=>[{x:p.x-g.itemWidth*.27,y:p.y+g.itemHeight*.20},{x:p.x+g.itemWidth*.27,y:p.y+g.itemHeight*.20}];const rest=[{x:leftShoulder.x-12,y:leftShoulder.y+15},{x:rightShoulder.x+10,y:rightShoulder.y+18}];
 if(t<.18){this.stage='reach';const paws=grip(item);left=this.mix(rest[0],paws[0],t/.18);right=this.mix(rest[1],paws[1],t/.18);}
 else if(t<.38){this.stage='lift';const lifted={x:g.source.x-12,y:g.source.y-45};item=this.mix(g.source,lifted,(t-.18)/.20);[left,right]=grip(item);angle=-9*Math.sin((t-.18)/.20*Math.PI);}
 else if(t<.58){this.stage='scan';const lifted={x:g.source.x-12,y:g.source.y-45};item=this.mix(lifted,g.scan,(t-.38)/.20);[left,right]=grip(item);angle=4;}
 else if(t<.85){this.stage='carry';item=this.mix(g.scan,g.aboveBag,(t-.58)/.27);item.y-=Math.sin((t-.58)/.27*Math.PI)*24;[left,right]=grip(item);angle=-4;}
 else{this.stage='release';const p=(t-.85)/.15;item=this.mix(g.aboveBag,g.insideBag,p);scale=1-p*.38;const paws=grip(g.aboveBag);left=this.mix(paws[0],rest[0],p);right=this.mix(paws[1],rest[1],p);}
 this.source.style.visibility=t<.18?'visible':'hidden';this.held.style.display=t<.18?'none':'block';this.held.style.left=item.x+'px';this.held.style.top=item.y+'px';this.held.style.transform=`translate(-50%,-50%) rotate(${angle}deg) scale(${scale})`;this.held.style.opacity=t>.94?1-(t-.94)/.06:1;
 const arm=(shoulder,paw)=>{const bend={x:shoulder.x+(paw.x-shoulder.x)*.48,y:Math.max(shoulder.y,paw.y)+13},size=Math.max(7,Math.min(15,g.itemWidth*.16));return `<path d="M${shoulder.x} ${shoulder.y}Q${bend.x} ${bend.y} ${paw.x} ${paw.y}" fill="none" stroke="#9c6f4d" stroke-width="${size*1.7}" stroke-linecap="round"/><path d="M${shoulder.x} ${shoulder.y}L${shoulder.x+(bend.x-shoulder.x)*.32} ${shoulder.y+(bend.y-shoulder.y)*.35}" fill="none" stroke="#3d8074" stroke-width="${size*2}" stroke-linecap="round"/><circle cx="${paw.x}" cy="${paw.y}" r="${size}" fill="#c28b5c"/><path d="M${paw.x-size*.32} ${paw.y-size*.2}v${size*.45}M${paw.x+size*.25} ${paw.y-size*.2}v${size*.45}" stroke="#a77753" stroke-width="2" stroke-linecap="round"/>`;};this.arms.innerHTML=arm(leftShoulder,left)+arm(rightShoulder,right);
 }
};
